# сценарии применения по IP/типу
def applications(p):
    ips = p.get('ip_list') or []
    cat = p['category']
    out = []
    if cat == 'trekovye-s20':
        out = ['Квартиры и апартаменты', 'Шоурумы и бутики', 'Галереи и экспозиции', 'Офисы и переговорные']
    elif cat == 'shinoprovod-s20':
        out = ['ГКЛ и натяжные потолки', 'Бетонные перекрытия', 'Переход стена–потолок']
    elif cat == 'bra':
        out = ['Спальни и отели', 'Коридоры', 'Входные группы'] if 65 in ips or p['slug'] == 'wall-600' else ['Спальни и изголовье', 'Гостиничные номера', 'Кабинеты']
    elif cat == 'lineynye':
        out = ['Офисы и open-space', 'Коридоры МОП', 'Торговые залы'] if not (54 in ips or 65 in ips) else ['Паркинги', 'Технические помещения', 'Уличные галереи']
    else:
        if 65 in ips or 54 in ips:
            out = ['Санузлы и ванные', 'Входные группы и козырьки', 'МОП и лифтовые холлы', 'Кухни']
        else:
            out = ['Жилые интерьеры', 'Лобби и МОП', 'Офисы', 'Рестораны и ритейл']
    return out


